def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}
    suite: str | None = None

    suite_re = re.compile(r"^\s*(?:Running|Doc-tests)\s+(.+?)\s*$")
    standard_re = re.compile(
        r"^test\s+(.+?)\s+\.{3}\s+"
        r"(ok|FAILED|ignored|ERROR|failed|skipped|passed|bench)"
        r"(?:\s.*|,.*|:.*)?$",
        re.IGNORECASE,
    )
    # Some libtest display modes omit the `test` label.
    dotted_re = re.compile(
        r"^(.+?)\s+\.{3}\s+"
        r"(ok|FAILED|ignored|ERROR|failed|skipped|passed|bench)"
        r"(?:\s.*|,.*|:.*)?$",
        re.IGNORECASE,
    )
    # Terse/alternate pretty output can put status first.
    leading_re = re.compile(
        r"^(ok|FAILED|ignored|ERROR|failed|skipped|passed)\s+(.+?)\s*$",
        re.IGNORECASE,
    )

    def normalize(status: str) -> str:
        status = status.lower()
        if status in {"ignored", "skipped"}:
            return "skip"
        if status in {"failed", "error"}:
            return "fail"
        return "pass"

    for raw_line in log.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        match = suite_re.match(line)
        if match:
            suite = re.sub(
                r"\s+\([^()]*\)$", "", match.group(1)
            ).strip()
            continue

        match = standard_re.match(line)
        if match:
            name, status = match.groups()
        elif suite is not None:
            match = dotted_re.match(line)
            if match:
                name, status = match.groups()
                # Exclude Cargo/libtest summaries and ordinary prose.
                if name.lower() in {"test result", "doc-tests"}:
                    continue
            else:
                match = leading_re.match(line)
                if not match:
                    continue
                status, name = match.groups()
        else:
            continue

        results[f"{suite or 'unknown-suite'}::{name.strip()}"] = normalize(status)

    return results
